{
  "gate_token": "td1Yi9bT2FnoNjDoMEciGA",
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unfolds her map at the edge of the ruined city.",
      "visual_description": "A windswept ridge at dusk overlooking a broken skyline of toppled spires and shattered stained glass, ink-stained coat fluttering, brass compass spinning wildly.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp warns of obvious traps ahead.",
      "visual_description": "A small oil lamp held aloft, single flame-eye narrowing toward distant castle gates, faint smoke curling into warning shapguage shapes.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "The tin fox sniffs a path through the rubble.",
      "visual_description": "A clockwork fox with blue glass eyes picking across cracked cobblestones, its key-wind tail clicking softly beside fallen royal banners.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "The glass diver arrives by stepping out of a cracked window.",
      "visual_description": "A figure in a clear diving helmet emerges from a tall broken pane, coat shimmering with reflected city lights, ripples spreading through the glass behind.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 5,
      "caption": "They ignore the looming castle gates and slip down a side alley.",
      "visual_description": "Massive iron gates carved with lions tower in the background while four small silhouettes turn deliberately into a narrow shadowed lane.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 6,
      "caption": "A cursed tower hums with tempting promises.",
      "visual_description": "A leaning tower wrapped in violet runes, whispering mouths etched into the stones, the oracle lamp's flame leaning away in refusal.",
      "characters": ["oracle_lamp", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "Rumors of a great winged beast rumble overhead.",
      "visual_description": "A vast shadow sweeps across rooftops; the tin fox flattens itself against a chimney, blue glass eyes wide and reflecting fire.",
      "characters": ["tin_fox", "glass_diver"]
    },
    {
      "scene_number": 8,
      "caption": "They find the sleeping tax collector slumped in a checkpoint booth.",
      "visual_description": "A plump official snoring on a ledger pillow inside a striped booth, stamped papers stuck to his sleeves, an unstamped rescue permit fluttering on the counter.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 9,
      "caption": "Mara forges his stamp herself and moves on.",
      "visual_description": "Close shot of an inked stamp slamming a paper marked PASSAGE GRANTED, the official still snoring, the tin fox tucking the document into its tail compartment.",
      "characters": ["mara_the_cartographer", "sleeping_tax_collector", "tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "Frightened townspeople peek from shutters and beg them to stop and listen.",
      "visual_description": "Pale faces in dozens of cracked windows along a narrow street, hands reaching out with notes; the glass diver presses on, eyes fixed forward.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 11,
      "caption": "An armored patrol marches past while the team hides in a fountain.",
      "visual_description": "Polished boots and pikes pass within inches of a dry tiered fountain; four heads peek up from behind the stone basin, the lamp's flame pinched dark.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 12,
      "caption": "The tin fox scouts ahead and finds the captive in the throne hall.",
      "visual_description": "The clockwork fox peers through a keyhole into a vast hall where a small figure sits chained beneath torn royal banners and a cracked chandelier.",
      "characters": ["tin_fox"]
    },
    {
      "scene_number": 13,
      "caption": "A magic door demands a riddle before it will open.",
      "visual_description": "An archway of shifting silver runes spirals like a whirlpool, the oracle lamp held close as its single eye blazes brighter, projecting the answer in smoke.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 14,
      "caption": "The glass diver dives through a tall mirror into the throne hall.",
      "visual_description": "A coat of broken reflections plunges into a full-length mirror that ripples like water, leaving Mara and the fox watching from the other side.",
      "characters": ["glass_diver", "mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 15,
      "caption": "Inside the hall, the diver frees the captive and lifts them through the mirror.",
      "visual_description": "A small hooded captive cradled in the diver's arms, chains snapping like icicles, the surface of the mirror bulging outward with their silhouette.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 16,
      "caption": "An armored patrol thunders after them through smoking streets.",
      "visual_description": "Lanterns and pike-tips swing wildly behind as the team sprints down a long colonnade, the tin fox skidding sparks off the flagstones.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "They race across the great bridge as it begins to collapse.",
      "visual_description": "A long stone bridge over a black river, sections falling away behind them in chunks, the oracle lamp's flame stretched horizontal by the wind.",
      "characters": ["glass_diver", "mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far shore, Mara marks the ruined city closed on her map.",
      "visual_description": "Dawn light over a quiet bank, the cartographer drawing a careful red X across a sketched skyline while the fox curls at her feet and the diver stands watch.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    }
  ]
}

